/*
* jQuery-Simple-timers
*
* Creates a countdown timers.
*
* Example:
*   $('.timers').starttimers();
*
*/
$( document ).ready(function() {
	var event = new Date();
	var hours = 23 - event.getHours();
	var minutes = 59 - event.getMinutes();
	var seconds = 59 - event.getSeconds();
	event = hours * 60
	+ minutes;
	$(".timers").data('minutes-left', event);
		$('.timers').starttimers({
			onComplete: function(){
			console.log('Complete');
		}
	});
});
(function($){

  var timers;

  var timers = function(targetElement){
    this.targetElement = targetElement;
    return this;
  };

  timers.start = function(options, targetElement){
    timers = new timers(targetElement);
    return timers.start(options);
  };

  timers.prototype.start = function(options) {

    var createSubDivs = function(timersBoxElement){
      var seconds = document.createElement('div');
      seconds.className = 'seconds';

      var minutes = document.createElement('div');
      minutes.className = 'minutes';

      var hours = document.createElement('div');
      hours.className = 'hours';

      var clearDiv = document.createElement('div');
      clearDiv.className = 'clearDiv';

      return timersBoxElement.
        append(hours).
        append(minutes).
        append(seconds).
        append(clearDiv);
    };

    this.targetElement.each(function(_index, timersBox) {
      var timersBoxElement = $(timersBox);
      var cssClassSnapshot = timersBoxElement.attr('class');

      timersBoxElement.on('complete', function() {
        clearInterval(timersBoxElement.intervalId);
      });

      timersBoxElement.on('complete', function() {
        timersBoxElement.onComplete(timersBoxElement);
      });

      timersBoxElement.on('complete', function(){
        timersBoxElement.addClass('timeout');
      });

      timersBoxElement.on('complete', function(){
        if(options && options.loop === true) {
          timers.resettimers(timersBoxElement, options, cssClassSnapshot);
        }
      });

      createSubDivs(timersBoxElement);
      return this.startCountdown(timersBoxElement, options);
    }.bind(this));
  };

  /**
   * Resets timers and add css class 'loop' to indicate the timers is in a loop.
   * $timersBox {jQuery object} - The timers element
   * options {object} - The options for the timers
   * css - The original css of the element
   */
  timers.prototype.resettimers = function($timersBox, options, css) {
    var interval = 0;
    if(options.loopInterval) {
      interval = parseInt(options.loopInterval, 10) * 1000;
    }
    setTimeout(function() {
      $timersBox.trigger('reset');
      $timersBox.attr('class', css + ' loop');
      timers.startCountdown($timersBox, options);
    }, interval);
  }

  timers.prototype.fetchSecondsLeft = function(element){
    var secondsLeft = element.data('seconds-left');
    var minutesLeft = element.data('minutes-left');

    if(secondsLeft){
      return parseInt(secondsLeft, 10);
    } else if(minutesLeft) {
      return parseFloat(minutesLeft) * 60;
    }else {
      throw 'Missing time data';
    }
  };

  timers.prototype.startCountdown = function(element, options) {
    options = options || {};

    var intervalId = null;
    var defaultComplete = function(){
      clearInterval(intervalId);
      return this.cleartimers(element);
    }.bind(this);

    element.onComplete = options.onComplete || defaultComplete;

    var secondsLeft = this.fetchSecondsLeft(element);

    var refreshRate = options.refreshRate || 1000;
    var endTime = secondsLeft + this.currentTime();
    var timeLeft = endTime - this.currentTime();

    this.setFinalValue(this.formatTimeLeft(timeLeft), element);

    intervalId = setInterval((function() {
      timeLeft = endTime - this.currentTime();
      this.setFinalValue(this.formatTimeLeft(timeLeft), element);
    }.bind(this)), refreshRate);

    element.intervalId = intervalId;
  };

  timers.prototype.cleartimers = function(element){
    element.find('.seconds').text('00');
    element.find('.minutes').text('00');
    element.find('.hours').text('00');
  };

  timers.prototype.currentTime = function() {
    return Math.round((new Date()).getTime() / 1000);
  };

  timers.prototype.formatTimeLeft = function(timeLeft) {

    var lpad = function(n, width) {
      width = width || 2;
      n = n + '';

      var padded = null;

      if (n.length >= width) {
        padded = n;
      } else {
        padded = Array(width - n.length + 1).join(0) + n;
      }

      return padded;
    };

    var hours, minutes, remaining, seconds;
    remaining = new Date(timeLeft * 1000);
    hours = remaining.getUTCHours();
    minutes = remaining.getUTCMinutes();
    seconds = remaining.getUTCSeconds();

    if (+hours === 0 && +minutes === 0 && +seconds === 0) {
      return [];
    } else {
      return [lpad(hours), lpad(minutes), lpad(seconds)];
    }
  };

  timers.prototype.setFinalValue = function(finalValues, element) {

    if(finalValues.length === 0){
      this.cleartimers(element);
      element.trigger('complete');
      return false;
    }

    element.find('.seconds').text(finalValues.pop());
    element.find('.minutes').text(finalValues.pop());
    element.find('.hours').text(finalValues.pop());
  };


  $.fn.starttimers = function(options) {
    timers.start(options, this);
    return this;
  };
})(jQuery);